# 期刊风格整体改写（覆盖 rewrites.py 中的同号段落）
S = {}

S[16] = "创新药是生物医药领域科技创新成果的重要载体，其价值实现须依次经过上市审评、医保准入与医疗机构遴选等环节，各环节依据不同规则对同一产品作出判断。评价规则是否清晰、能否有效衔接，直接影响研发主体在临床研究设计、比较药品选择与证据准备上的预期。《中华人民共和国国民经济和社会发展第十五个五年规划纲要》[1]提出健全医疗、医保、医药协同发展和治理机制，优化创新药审评审批，健全医保支持创新药的机制；2025年出台的《支持创新药高质量发展的若干措施》[2]进一步推动研发、准入与使用衔接，同年发布的首版商业健康保险创新药品目录（以下简称商保创新药目录）自2026年1月起实施[3]。“十四五”期间，我国共批准创新药230个，其中2025年76个[4]；2025年国家医保药品目录新增114种药品，其中1类创新药50种，首版商保创新药目录纳入19种药品[5]。与此同时，当年仍有10余个1类创新药未通过医保目录专家评审，原因主要在于与目录内同类药品重复而临床价值未见提升，或价格超出基本医保“保基本”功能定位、与价值不匹配[6]。这表明，上市审评与医保准入回答的是不同的价值判断问题，研发主体如何在研发阶段预判后续环节的证据要求，已成为创新决策中的现实问题。"

S[17] = "从科技创新管理视角看，上述问题的实质是跨部门评价规则能否为创新主体提供稳定、可预期的制度环境。创新药从获批上市、纳入医保到进入临床，分别涉及国家药品监督管理局（以下简称药监局）、国家医疗保障局（以下简称医保局）和国家卫生健康委员会（以下简称卫健委）的评价安排，各环节的评价目的与比较药品各有侧重。课题组的专家访谈与调研纪要（I01、I02）显示，获批上市的1类创新药未必满足医保评审对临床价值的要求，纳入医保目录的药品在医疗机构的配备使用中亦可能受阻。若各环节所依据的证据及其用途缺乏清晰界定，研发主体难以判断既有研究能够支撑哪些结论、后续还需补充哪些证据，规则的不确定性便会转化为证据准备中的重复投入。因此，跨部门协同的关键不在于以单一标准取代各部门评价，而在于厘清各环节的证据要求及其衔接条件，在保障评价质量的前提下提高证据使用效率，实现创新药评价的质效协同。"

S[18] = "鉴于此，本文从科技创新治理中的跨部门协同视角出发，构建“制度逻辑—组织注意力”分析框架，对三部门2017—2026年涉及创新药上市、准入和使用评价的51个政策来源进行编码，并结合政策条文与访谈资料，回答以下两个问题：（1）三部门政策文本对安全性、有效性、经济性、创新性和公平性五维评价内容的关注重点有何差异？（2）在同一维度下，三部门的评价对象、比较药品与结论用途有何不同，既有评价结论用于后续环节需满足哪些条件，对增强评价规则可预期性有何启示？"

S[21] = "已有关于创新药评价的研究主要围绕价值评估制度、主体互动与政策工具3个层面展开。在价值评估方面，孔繁翠[7]比较英、德、法、加四国的创新药价值评估制度，建议建立附加临床收益评估及分级体系；赵华婷等[8]基于法国经验，主张以临床价值分级与再评价支撑医保目录动态调整；艾丹丹等[9]强调以公开透明的多维评价标准支持基于价值的定价与支付。在主体互动与政策工具方面，王恩楠等[10]运用演化博弈模型分析医保谈判策略，吕倩鹏等[11]对65份国家层面创新药研发政策的量化分析发现政策工具内部结构失衡。总体而言，上述研究多聚焦医保准入或研发政策等单一环节，较少在统一框架下比较不同部门对同一药品的评价要求。科技创新政策研究则表明，政策内容的比较应结合其所服务的创新环节，刘仁济等[12]即从政策工具在创新价值链上的分布考察科技成果转化政策。对创新药而言，研发阶段形成的证据能否支撑后续支付与临床应用决策，正是评价规则与创新链衔接的具体体现。"

S[23] = "国际研究表明，比较不同机构的评价结论需区分其评价标准与证据要求。Casilli等[13]比较法、德、意三国对189个药品/适应症的健康技术评估（Health Technology Assessment，HTA）结论，发现德法一致率为82%，意法和意德分别为52%和57%，纳入意大利创新性认定中的证据质量因素后分别升至72%和74%。Garau等[14]针对意大利19名患者代表、临床医生和支付方人员的研究发现，临床医生更重视疾病严重性与比较疗效，支付方则更关注未满足需求、比较成本及证据质量。"

S[24] = "Kållberg等[15]对欧美药品监管与HTA机构19名参与者的研究表明，各方对抗生素新颖性的理解标准不一，临床数据有限亦制约上市评价、HTA与临床使用之间的证据衔接。Mundy等[16]指出，HTA对创新的界定与评价尚不统一，创新因素往往隐含于优先排序及药品定价、报销决策之中。国内研究中，李梦颖等[17]基于制度逻辑理论分析医保谈判药品在医疗机构的配备与使用，揭示了国家逻辑、市场逻辑、社会逻辑与专业逻辑之间的冲突与联系。上述研究表明，评价差异根植于各方的评价标准、证据要求与制度环境。科技成果评价研究进一步强调，应依据评价对象、任务与情境开展分类评价，并限定评价结论的适用范围[18]。据此，上市审评、医保准入与临床使用可视为针对同一创新成果、服务于不同任务的分类评价；但药品评价具有法定程序与专门技术规则，仍需结合药品政策规则展开具体比较。"

S[26] = "既有研究已讨论政府在医疗与医保治理中的主动管理角色[19]及健康技术评估在医保目录调整中的应用[20]，国际研究亦比较了不同国家HTA结论的一致性[13]与监管、HTA机构对新颖性的理解[15]。然而，现有文献或从医保准入角度讨论创新药价值评估，或从政策工具角度分析研发支持政策，较少在统一评价维度下比较药品注册、医保准入与临床使用主管部门的关注重点，也较少从创新主体证据准备的角度考察跨环节评价规则的衔接。同一评价维度可能服务于不同决策，仅比较关注比重难以揭示既有证据用于后续环节的条件。基于此，本文以五维框架比较三部门的关注重点及维度共现，结合具体条文分析评价对象、比较药品、证据要求与结论用途，并从证据适用条件出发，探讨增强评价规则可预期性的跨部门协同路径。"

S[29] = "本文以药品注册分类界定创新药。《药品注册管理办法》[21]将中药、化学药和生物制品分别划分为创新药、改良型新药等类别；《化学药品注册分类及申报资料要求》[22]将化学药品1类界定为境内外均未上市、含有新的结构明确且具有药理作用的化合物，并具有临床价值的创新药。《支持创新药高质量发展的若干措施》[2]（以下简称《若干措施》）提出增设商保创新药目录，重点纳入创新程度高、临床价值大、患者获益显著且超出基本医保保障范围的创新药。可以看出，注册分类兼顾化合物新颖性与临床价值，医保支付则进一步考虑患者获益与保障范围。由于创新药上市时临床数据往往有限[15]，且各方对创新的界定与评价不尽一致[16]，其价值判断在各环节之间更难直接互认。除突破性治疗等加快上市程序[21]和商保创新药目录等专门安排外，创新药主要适用通用的药品评价规则，故本文比较三部门评价创新药所依据的政策规则，而不限于以“创新药”命名的文件。相应地，本文所称“创新药评价”，是指三部门政策文本中适用于创新药上市审评、医保准入和临床使用的评价规则及其关注重点，而非具体品种的评审结论。这些规则构成创新主体安排研发与证据准备的重要制度依据。据此，本文比较各环节对企业证据准备的要求，并探讨如何通过比较药品沟通、补充研究与临床应用反馈增强评价规则的可预期性，促进创新药研发、准入与使用的衔接。"

S[30] = "制度逻辑视角有助于解释三部门对创新药价值判断的差异。该视角强调实践、价值和规则与认知、行动及制度环境之间的关联[23]，并关注组织如何回应多重制度要求[24]。在创新药领域，药品注册、医保准入和临床使用分别由药监局、医保局和卫健委主导，构成服务于不同决策目标的制度安排；三者作用于同一创新产品，使研发主体面临多重制度要求。本文据此考察这些目标在评价对象、证据要求和结论用途上的具体体现。"

S[31] = "制度逻辑揭示了三部门决策目标的差异，而这种差异如何转化为政策文本关注重点的差异，可由注意力基础观加以解释。Ocasio[25]认为，组织决策取决于决策者关注的议题与应对方案，关注内容随具体决策情境而变化（情境注意力），注意力分布则受规则、资源与关系的约束（注意力的结构性分配）。练宏[26]指出，比较不同组织的关注重点需考虑其组织与制度环境；李梦颖等[17]则将制度逻辑与医药政策主体的注意力配置相联系。由于三部门的决策情境及规则与资源约束不同，其政策文本对五维评价内容的关注比重可能存在差异。"

S[32] = "政策文本的内容选择为测量上述差异提供了途径。政府注意力研究通常以正式政策文本的内容选择刻画组织关注重点[27]：文宏[28]以关键词所在句段及其语境测量基本公共服务注意力；陈星平等[29]按同一句段在同一维度计一次、在不同维度分别计数的原则比较关注内容的构成。借鉴上述做法，本文将“部门注意力配置差异”界定为三部门对五维评价内容关注比重的差异，并以“注意力占比”衡量，即某维度编码为1的句段数占该部门五个维度编码为1的句段数之和的比例；同一句段可计入多个维度，但在同一维度至多计一次。在比较关注结构的基础上，本文进一步结合条文与访谈，考察同一维度下证据要求及其用途的差异，以识别跨环节证据准备中需要协调的具体事项。"

S[34] = "借鉴李梦颖等[17]的医药政策分析思路，本文依据三部门核心文件的政策目标概括其制度逻辑。《药品注册管理办法》[21]要求保证药品安全、有效和质量可控，并明确临床价值导向，体现科学—安全逻辑；《基本医疗保险用药管理暂行办法》[30]（以下简称《暂行办法》）以提高基金使用效益为目标，将临床必需、安全有效、价格合理列为目录准入条件，体现经济—效率逻辑；《药品临床综合评价管理指南（2021年版 试行）》[31]（以下简称《管理指南》）强调保障基本用药供应、规范使用并满足用药需求，体现公共服务逻辑。三种逻辑概括了各部门的主要决策任务，彼此并不排斥，安全有效与临床价值是三部门共同关注的基础（表1、图1）。据此提出预期：药监局以安全性、有效性为主，医保局以经济性为主，卫健委在安全性与公平性上相对突出。"

S[42] = "研究时段为2017年至2026年7月，研究对象为公开的药品评价政策及配套官方材料。2017年，人力资源社会保障部将36种谈判药品纳入医保目录乙类范围[32]，中办、国办印发《关于深化审评审批制度改革鼓励药品医疗器械创新的意见》[33]，统筹部署审评审批、医保支付与医疗机构使用新药，故以2017年作为三部门政策的共同起点。"

S[43] = "参照吕倩鹏等[11]的政策筛选方法，以“创新药”“合理用药”“双通道”“药品注册”“药品审评审批”“医保药品目录”“药品临床综合评价”为标题关键词，于2026年7月6日在北大法宝V6中央法规数据库精确检索2017—2026年的部门规章、部门规范性文件和部门工作文件，并从相关部门官网补充附件及配套材料。在此基础上，剔除纯药品清单、年度审评报告、按疾病诊断相关分组和按病种分值付费的技术规范、逐年临床用药手册，以及已有正式版的征求意见稿。"

S[44] = "最终纳入51个政策来源，其中药监局17个、医保局24个、卫健委10个（示例见表2，完整清单见补充材料B）；党中央、国务院或中办、国办发布的4份文件作为共同制度背景。一个政策来源可包含通知、附件或配套官方问答，同一正文重复发布仅计一次；联合发文按制度系统归属计入一个部门，并通过剔除联合文本检验该处理的影响。卫健委对药品临床使用的评价主要体现于药事管理、处方审核和合理用药等文件，故将此类文件纳入。由于纳入来源包含适用于全部药品的文件，各部门组文本中含“创新药”一词的句段分别为药监局98条、医保局144条、卫健委0条。"

S[49] = "访谈资料包括专家访谈纪要（I01）和医保专家调研纪要（I02），均由课题组整理。访谈前已向受访者说明研究目的，并获得匿名引用的口头同意。I01记录于2025年6月9日，涉及医保准入评审的机制与流程、医保体系存在的问题及政策建议；I02涉及目录评审分层、临床价值评价及流程优化。药品监管环节主要依据公开技术文件。访谈内容按评价对象、证据要求和结论用途归类，并与相应政策条文相互印证，仅用于阐释评价要求及跨环节实施问题，不作为检验研究结论的依据。"

S[52] = "本文采用医保目录调整中的安全性、有效性、经济性、创新性、公平性五维框架。《目录调整申报指南》[34]（以下简称《申报指南》）要求按上述五个维度组织申报材料，2023—2026年维度名称保持不变，且同时适用于基本医保目录和商保创新药目录调整；《常用问答（2026年版）》[35]（以下简称《常用问答》）亦要求从多维度综合研判药品价值。以该框架为统一比较尺度，并依据各部门条文的实质内容编码，能够识别药监局获益风险评价与卫健委药品临床综合评价中的对应内容。需要说明的是，统一尺度仅用于描述关注结构，并不意味着三部门应采用相同的评价标准或维度权重。《管理指南》[31]原设安全性、有效性、经济性、创新性、适宜性、可及性六个维度，其中涉及药品获取保障与可负担性的内容归入本文的公平性，适宜性则按原政策含义处理。《申报指南》公平性栏目中的价格信息按费用内容编码为经济性，若同时涉及患者负担或药品获取保障，则另记为公平性。"

S[53] = "本文同时采用自动规则编码（以下简称规则编码）与大语言模型（Large Language Model，LLM）编码处理全部文本。规则编码基于领域词典与语境规则，判断表述是否针对药品，并识别适用范围、上级条款及否定关系；LLM编码依据完整编码手册，结合待编码句段及必要上下文给出五维判断与原文依据。LLM编码采用GPT-6.1 Sol模型，推理强度设为ultra，每批处理1～12条，各批使用独立上下文，且不提供人工标签或其他机器结果，其余生成参数采用服务默认设置；提示词与输入输出记录可向通信作者索取。词典分类的质量检验参照Kroon等[36]，LLM编码参照Gilardi等[37]及Halterman和Keith[38]。两种方法基于同一版政策原文及上下文，遵循相同的五维定义与纳入、排除条件。"

S[54] = "本文以具有完整政策含义的句段为分析单元，并保留上级条款、表头及前后文，以确定表述对象与适用条件。三部门共计4 481条句段，其中药监局1 848条、医保局2 100条、卫健委533条。同一句段可同时编码多个维度，如“降低患者用药负担”同时编码为经济性和公平性，而降低企业申报费用则不编码为公平性。"

S[56] = "本文将安全性、有效性、经济性、创新性、公平性分别记为S、E、Ec、I、F。安全性指药物损害、用药风险及其识别、评价与控制；有效性指防治效果、临床获益及相应证据；经济性指药品价格、费用、支付与成本效果；创新性指技术创新、实质改良及其资格评价，以及明确的创新研发支持；公平性指对用药公平性的实质评价要求，或患者按治疗需要获得并持续使用所需药品的机会与负担，一般性可及表述或程序名称本身不构成编码依据。各维度在句段层面分别编码：符合定义记为1（正类），不符合记为0，信息不足而无法判断的保留为待定。详细的纳入、排除条件见补充材料A。"

S[57] = "注意力占比按第2.1节定义计算，五维合计为100%；内容覆盖比例以部门全部句段数为分母，由于同一句段可涉及多个维度，其合计不必为100%。条件比例指涉及某一维度的句段中同时涉及另一维度的比例，用于刻画维度共现。以安全性句段中同时涉及有效性的比例（记为E|S）为例，分子为两维均判为1的句段数，分母为安全性判为1且有效性可判定的句段数。各指标均基于4 481条全量编码计算，待定项单独保留。"

S[59] = "人工核验共纳入466条句段，采用重点类别全查与按部门分层随机抽样相结合的方式：166条重点类别句段全部核验，另从三个部门各随机抽取100条，合计药监局106条、医保局202条、卫健委158条。重点类别涵盖药监局的经济性内容及医保局、卫健委的安全性和公平性内容，以加强对稀少类别及关键组合的检验。人工核验由两名编码员完成，一名为参与编码手册设计的作者，另一名为未参与设计、编码前经统一培训的同课题组研究生。两人在不查看规则编码与LLM编码结果的情况下，对照原文及必要上下文独立判读全部466条句段的五个维度，分歧经讨论后定稿，共形成2 330项0/1人工标签。"

S[60] = "参照Grimmer和Stewart[39]针对具体研究任务开展验证的原则及Gilardi等[37]对照机器与人工标注的做法，本文按维度报告Cohen {i:κ}系数[40]、精确率、召回率及F1值。精确率为机器判为1的句段中经人工确认的比例，召回率为人工判为1的句段中被机器识别的比例，F1为二者的调和平均数；各指标仅在机器与人工均可作二元判断的项目上计算，机器待定项单列，不改记为0。两名编码员独立判读的{i:κ}在安全性、有效性、经济性、创新性和公平性上依次为0.919、0.925、0.947、0.896和0.765，2 330项中有58项不一致。按Landis和Koch[41]的标准，{i:κ}为0.61～0.80表示高度一致，0.81～1.00表示几乎完全一致。比较结果见表3。"

S[63] = "在466条核验样本中，LLM编码在安全性、有效性、经济性和公平性四个维度的{i:κ}与F1均高于规则编码，仅创新性维度规则编码略高（表3）。五维合并后，LLM编码的{i:κ}、F1与召回率分别为0.926、0.940和0.988，规则编码分别为0.765、0.799和0.690，后者仅精确率略高（0.951对0.897）；除创新性外，规则编码其余四个维度的召回率为0.629～0.689，即约三成人工判为1的句段未被识别。LLM编码在经济性和公平性上的精确率相对较低（0.864和0.821），故第5.1节和第5.2节另以规则编码对相关结果进行对照。"

S[64] = "为检验LLM编码的可重复性，本文以同一模型、编码手册和逐条材料对466条核验样本重新运行一次，批次组成与并发设置均不同于全量运行。两次结果各维度{i:κ}在0.926～1.000之间，438条句段（93.99%）的五维判断完全一致；复跑结果与人工标签的五维合并{i:κ}为0.929（原结果为0.926），各维度{i:κ}在0.876～0.954之间。"

S[65] = "综合各维度{i:κ}、F1及具体判读结果，本文以LLM编码作为部门比较的主要依据；创新性维度两种方法的{i:κ}均高于0.93，为统一五维口径亦采用LLM结果。规则编码作为方法对照，用于检验主要结论是否随编码方法而改变。"

S[68] = "部门差异的检验方法如下：各维度内容覆盖比例采用3×2卡方检验并报告Cramér’s {i:V}（以0.10、0.30和0.50分别作为小、中、大效应的参考值[42]），部门两两比较和条件比例比较采用Fisher确切概率法并进行Bonferroni校正[43]，以校正后{i:P}<0.05为差异具有统计学意义；注意力占比、条件比例及其部门差异在部门内以政策来源为单位重抽样5 000次[44]，估计95%置信区间（confidence interval，CI）。由于同一政策来源的句段并非相互独立，表6报告按来源重抽样的区间，句段重抽样区间及完整检验结果见补充材料F。各项检验均剔除待定项。"

S[71] = "LLM全量编码结果显示，药监局侧重安全性与有效性，两维合计占68.38%；医保局以经济性为主，占76.48%；卫健委的安全性（39.37%）与经济性（28.35%）占比较高（表4、图2）。药监局创新性占20.96%，高于医保局（5.84%）和卫健委（3.94%），相关内容主要涉及创新药注册分类、临床价值导向和研发支持（表5）。就含“创新药”一词的句段而言，药监局98条句段中创新性和安全性的注意力占比分别为45.35%和29.07%，医保局144条句段中经济性和创新性分别为41.67%和22.92%，卫健委组文本无此类句段。这表明两部门针对创新药的条款更突出创新性，但医保局仍以经济性居首。按是否为专门针对创新药的来源拆分后，两部门的主要关注维度均与全部来源一致（表7；规则编码对照见补充材料表D4、D5）。"

S[77] = "规则编码在经济性和公平性上的精确率较高（表3），以其对照部门关注结构，结果与LLM编码基本一致：药监局侧重安全性与有效性，医保局经济性占76.87%（LLM编码为76.48%），卫健委安全性占比较高。在三部门两两比较的15项注意力占比差异中，13项方向一致，不一致的2项为药监局与卫健委在安全性和公平性上的相对排序。LLM编码下两部门安全性占比分别为40.44%和39.37%，公平性占比分别为10.20%和11.81%，差距均不足2个百分点，且卫健委五维标签仅127个，因此不认为两部门在这两个维度上存在稳定的高低关系（补充材料E）。三部门五维内容覆盖比例见图3。"

S[81] = "需要指出的是，图2与图3的分母不同：医保局经济性句段878条，占全部2 100条句段的41.81%（图3），占五维标签合计1 148个的76.48%（图2）。在九种统计口径及逐一剔除来源后，LLM编码下药监局安全性居首、医保局经济性居首的结论均保持不变；卫健委按全部句段以安全性居首，但剔除联合来源或2022年加强用药安全管理文件后转为经济性居首（补充材料D）。卫健委50条安全性句段中有29条来自两份联合发文，即2022年加强用药安全管理文件（18条）和《医疗机构处方审核规范》（11条）；剔除前者后，安全性与经济性句段分别为32条和36条，仅保留单独发文来源时为8条和23条。由此可知，卫健委安全性居首主要源于联合发文，该排序对来源构成较为敏感。"

S[82] = "句段层面的检验表明，五维内容覆盖比例的部门差异均具有统计学意义（{i:χ}{sup:2}=44.44～1 107.27，{i:P}均<0.001，Cramér’s {i:V}为0.100～0.498）；医保局经济性占比与药监局创新性占比均高于另两部门，按政策来源重抽样的95%CI不含0，且两种编码结果一致。卫健委内部安全性与经济性、药监局内部安全性与有效性的先后则无法确定（表6）：药监局这两类句段分别集中于安全性总结资料、风险管理计划等技术文件与抗肿瘤药物研发、真实世界证据等指导原则，按来源重抽样时其先后随样本构成而变化。上述占比反映的是政策文本中五维评价内容的构成，而非实际评审权重，其对创新药证据准备的含义需结合具体条文进一步分析。"

S[84] = "安全性句段中同时涉及有效性的比例（E|S）以医保局最高：LLM编码下医保局为81.01%（64/79），药监局为42.60%（187/439），卫健委为26.00%（13/50）。医保局与另两部门的差异具有统计学意义，药监局与卫健委的差异不显著（表6），这与卫健委分母较小且来源集中有关。该结果在规则对照与各项稳健性分析中保持不变；按完全相同文本、规范化文本和近似文本（相似度≥0.85）三种方式去除重复援引条款后，医保局E|S在LLM编码下为76.74%～81.67%，在规则编码下为60.00%～70.00%，均高于另两部门（补充材料表D3）。"

S[85] = "政策条文与访谈资料均支持上述结果。《暂行办法》第七条将安全有效、临床必需和价格合理共同列为目录准入条件[30]，《申报指南》要求说明创新带来的疗效或安全性优势[34]；I02将安全性、有效性和经济性列为综合评审的核心内容，I01所述综合组评价的六个维度亦涵盖上述三项。这表明，医保局较少单独论述安全性，而是将其与疗效一并作为准入条件。卫健委该比例较低，主要因其安全性句段多涉及用药错误防范与处方审核流程，在2022年加强用药安全管理文件和《医疗机构处方审核规范》中分别仅为5.56%（1/18）和9.09%（1/11）。因此，维度共现反映的是同一维度在不同任务中的内容组合，而非部门之间的实际合作程度。"

S[86] = "经济性句段中同时涉及公平性的比例（记为F|Ec）卫健委高于医保局，但该结果对编码方法与来源构成较为敏感。在两维均可判定的句段中，LLM编码下卫健委为13.89%（5/36），医保局为2.96%（26/877）；该差异经校正后具有统计学意义，但按政策来源重抽样的95%CI包含0，且规则编码下不显著（表6）。LLM结果在九种统计口径及逐一剔除来源后方向不变，规则编码在剔除联合来源或2024年基层药品联动管理文件后则发生反转（补充材料D），原因在于共现句段少且来源集中，LLM编码下卫健委5条共现句段中有4条来自《管理指南》（表5）。若以公平性句段为分母（记为Ec|F），LLM编码下医保局为60.47%（26/43），卫健委为33.33%（5/15），差异不显著（表6）。两项比例方向相反源于分母不同：医保局经济性句段基数较大（877条），F|Ec相应偏低，而其保障类表述多与费用相关联，故Ec|F较高。"

S[89] = "药监局的安全性与有效性内容主要围绕药品研发及上市所需的获益风险证据展开。《创新药研发期间风险管理计划撰写技术指导原则（试行）》[45]要求识别影响获益风险平衡或受试者安全的风险，并制定预防、监测和治疗措施；抗肿瘤药物研发指南[46]强调试验对照选择与患者获益终点之间的关联。药监局经济性的注意力占比较低，内容包括真实医疗实践中的经济学效益评估[47]，以及2026年发布的《药物临床试验质量管理规范》[48]第四十五条规定的免费供药与医学检测费用责任；公平性内容主要为《药品注册管理办法》[21]第六十八条对临床急需短缺药品的优先审评安排。"

S[90] = "医保局的经济性评价涵盖药价、治疗费用、销量预测、支付范围与基金影响。《申报指南》[34]要求报告未来两年的销量与基金影响，《谈判药品续约规则》[49]依据实际药品费用与预算之比安排续约及支付标准调整；《常用问答（2025年版）》明确支付费用监测与药品供应要求，并说明谈判药品支付标准包含基金与参保人员共同支付的费用[50]；《若干措施》[2]提出通过协商合理确定商保创新药目录内药品的结算价。卫健委《管理指南》[31]将价格水平、可获得性和可负担性共同纳入可及性评价，并以年用药治疗费用占家庭年可支配收入的比重衡量可负担性；药品监测政策[51]进一步要求共享信息、保障供应并应用评价结果。由此，经济性与公平性的关联主要体现在费用分担与支付保障、药品供应及临床使用等方面。"

S[96] = "关注比重与维度共现揭示了政策内容的分布特征，但同一维度仍可能服务于不同评价任务，相关结论在使用时需核对目标人群、比较药品与证据要求。本文以“比较药品”统称各环节与目标药品进行比较的药品，包括临床试验的阳性对照药（以下简称试验对照药）、医保目录调整的参照药（以下简称医保参照药）和临床综合评价的参比药（以下简称临床参比药）。以下从创新性、有效性与证据要求、价值衡量三个方面比较三部门的相关规定。"

S[97] = "在创新性方面，药监局《化学药品注册分类及申报资料要求》[22]同时考察化合物新颖性与临床价值；医保局要求申报材料说明创新带来的疗效或安全性优势[34]，续约规则将1类药品注册分类用于特定条件下的谈判选择[49]；卫健委《管理指南》[31]通过与参比药的比较考察药品满足临床需求的程度，并关注治疗空白、未满足需求及自主研发。三部门均重视创新的临床意义，但评价结论分别服务于分类注册与研发支持、支付决策以及医疗机构的药品遴选与配备。I02指出，获得创新药注册分类并不意味着能够实现企业预期的谈判价格。因此，研发主体在准备后续评价材料时，应结合具体人群与比较药品阐明临床价值。"

S[98] = "在有效性与证据要求方面，药监局抗肿瘤药物研发指南[46]要求阳性对照反映目标患者在临床实践中的最佳治疗选择；医保局《申报指南》[34]要求与试验对照药及目录内同治疗领域药品进行比较，《常用问答》[35]进一步明确参照药原则上应为临床应用最广泛的同治疗领域、同作用机制的目录内药品；卫健委《管理指南》[31]重视参比药、最佳可得研究证据及真实世界数据，必要时开展亚组分析。因此，使用既有研究结果时，应在同一人群和治疗线别下核对试验对照药、医保参照药与临床参比药的异同，判断原有证据能否直接使用或需补充比较，并据此确定后续研究的人群与比较药品。"

S[99] = "在价值衡量方面，药监局通过获益风险判断支持上市审批与风险控制；医保局通过相对临床价值、药品费用及基金影响评估支持医保准入与支付；卫健委通过安全性、有效性及增量经济分析支持医疗机构的药品遴选、采购使用与资源配置[21，30，31]。结合I02关于临床价值分层与经济评价衔接的讨论，经济评价方法虽可用于不同环节，但各项评价需分别明确分析视角、成本范围、适用人群及所服务的决策。因此，不同环节可共享部分研究材料，但评价结论须依据各自的决策用途加以解释。"

S[101] = "从制度逻辑视角看，三部门关注结构的差异与其承担的决策任务相对应。药监局的科学—安全逻辑体现为研发与上市环节对获益风险及证据充分性的重视；医保局的经济—效率逻辑体现为公共支付中对相对临床价值与资源约束的关注；卫健委的公共服务逻辑则体现为对安全合理用药、药品供应与临床需求的重视。对照研究预期，药监局和医保局的结果与预期相符；卫健委安全性占比较高，但公平性占比（11.81%）与药监局（10.20%）接近，预期仅得到部分支持。这与卫健委的来源构成有关：其10个来源中有7个为合理用药、处方审核和医疗质量类文件，合计占其句段的68.11%；15条公平性句段中有9条来自2024年基层药品联动管理文件。上述文本主要规范药品进入医疗机构后的一般使用，公共服务目标更多体现为用药安全与合理用药要求。"

S[102] = "从注意力基础观看，关注比重与内容组合分别反映组织关注的结构与具体情境。医保局对经济性的集中关注与其承担的基金影响报告、续约支付标准调整等任务相对应[34，49]，在含“创新药”一词的句段中经济性仍居首；医保局安全性与有效性的高共现表明，在准入情境中安全性多与疗效共同构成判断条件；药监局含“创新药”一词的句段则集中于创新性，服务于注册分类与研发支持。因此，各部门在某一维度上关注比重的差异，并不意味着其对药品价值的判断相互排斥；相同维度的表述亦不能等同于相同的评价要求，仍需结合政策条文辨明各环节所回答的决策问题及证据使用条件。"

S[103] = "上述差异意味着，创新药在某一环节形成的评价结论进入下一环节时，需要重新说明其适用条件。医保局申报要求引用药审技术评审报告[34]，表明上市审评证据可为医保评价提供部分依据；卫健委同时评价价格与药品获取情况[31]，将支付条件与医疗机构配备、临床使用相联系。I01反映，部分药品纳入医保目录后在医疗机构的配备与使用仍然受限，说明药品的实际应用还取决于医疗机构的临床需求与用药条件。因此，跨部门协同的重点不在于统一各部门的评价维度，而在于明确评价结论的适用条件，即针对同一人群核对比较药品，说明既有证据能够回答哪些问题、哪些问题有待补充研究。以适用条件为核心的协同，既保留了各部门依法履职所需的独立判断，又有助于减少因证据要求不清导致的重复论证，体现了兼顾评价质量与效率的质效协同取向。"

S[104] = "从科技创新管理视角看，评价规则的可预期性是创新主体配置研发资源的重要前提。企业在设计临床研究、准备后续评价材料或安排补充研究时，需要明确各环节对研究人群、比较药品、观察结果与分析视角的要求。若跨部门沟通能够尽早说明既有证据可服务于哪些评价、尚需补充哪些研究，企业即可将证据规划前移，在研发阶段统筹考虑准入与使用环节的需要；支付与临床使用环节的反馈，也可为识别后续研究问题提供信息。对于不同评价可共用的数据，可在质量要求相符的前提下统筹采集，各部门仍依据各自目的作出判断。在此意义上，跨部门协同为创新提供的“确定性”并非对评审结果的事先确定，而是对证据要求、比较基础与结论用途的明确。"

S[106] = "围绕增强评价规则可预期性、促进研发—准入—使用环节质效协同的目标，结合前文对评价对象、比较药品与证据要求的比较，本文从证据准备的前端、中间和后端3个环节提出跨部门协同路径。"

S[108] = "比较药品与证据要求的前置沟通位于研发证据形成与后续评价之间，是降低证据要求不确定性的前端环节。前文分析表明，上市审评、医保准入与临床综合评价在比较药品选择及证据用途上存在差异，既有证据进入后续评价前，应先核对其适用条件，再明确补充研究需求。现行《参照药预沟通办法（试行）》[52]规定，符合条件的1类化学药、1类治疗用生物制品及1类中成药可申请推荐参照药，适用范围包括符合年限要求的已上市药品，以及上市申请已受理并通过技术评审的未上市药品；经医保局组织专家论证推荐的参照药，可供企业在药物经济学或真实世界研究中选用。该机制将比较药品沟通前置于后续评价研究，为企业安排证据准备提供了参考。"

S[109] = "在此基础上，可从以下三方面加以完善：一是由申请企业按适应症说明研究人群、治疗线别，以及试验对照药与意向医保参照药的差异和选择理由，供专家论证时核对；二是结合《申报指南》[34]要求提交的药审技术评审报告，说明既有研究与拟开展评价在人群、比较药品和观察结果上的异同，并在反馈中明确既有证据可参照的范围及需补充论证的问题；三是结合2026年药品价格政策[53]对创新类别和临床价值的区分，分别说明注册分类、相对临床获益与支付评价所依据的证据。当市场环境或药品说明书发生重大变化时，企业可按预沟通办法重新申请；新增临床证据涉及原有比较判断的，应说明相应变化。需要强调的是，预沟通旨在帮助企业尽早明确比较基础，申请品种仍需参加正式评审[54]，其结果不构成对准入或价格的承诺。"

S[111] = "补充研究是衔接上市证据与支付、使用证据的中间环节。不同评价任务对研究人群、比较药品和观察内容的要求各异，创新药上市后需补充的证据也应按用途加以区分。对于附条件批准等负有上市后研究义务的品种，《药品注册管理办法》[21]第六十六条规定持有人应当采取风险管理措施并完成相关研究。2025年真实世界医保综合价值评价试点通知[55]提出于2026年建设数据库、开展评价并形成初步成果；2026年1月，首批国家可信评价点网络已组建[56]。《若干措施》[2]亦鼓励创新药开展真实世界研究，推动研究结果与目录准入、续约及医保支付范围调整挂钩。依托上述安排，可针对负有上市后研究义务或支付评价证据不足的品种分别明确待回答的问题，由企业、专业评价团队与参与医疗机构共同商定所需的研究人群、比较药品、终点、随访期限及数据质量要求。"

S[112] = "补充研究统筹的重点在于数据准备与研究安排的衔接。对于不同任务可共用的临床数据，应在使用权限、研究人群、观察内容与质量要求相符的前提下协调采集字段和随访安排；药物警戒、医保价值评价与临床综合评价仍应依据各自目的开展研究设计与分析，并说明结论的适用范围。在组织分工上，医保部门按试点通知统筹组织医保评价，上市许可持有人继续履行法定的上市后研究义务，参与医疗机构负责相应的数据质量与随访；研究启动前应明确各项结果的提交时点与证据更新方式。"

S[113] = "在结果应用上，补充研究应聚焦原有证据尚未回答的问题，说明新增结果对临床价值判断及后续管理的意义，并区分医保价值评价与药物警戒、附条件上市研究、临床综合评价的不同用途[21，31，55]。现阶段可在既有协议与权限范围内，明确新增证据用于目录续约、支付范围调整或相关评价的条件。通过统筹补充研究，能够在不降低评价质量要求的前提下减少同类数据的重复采集，提高证据生成与使用效率。"

S[115] = "临床应用是创新药价值实现的后端环节，也是识别后续研究问题的重要信息来源。前文对评价用途的比较与I01的访谈内容均表明，医保准入结论尚不足以说明药品是否适合在具体临床条件下使用。《若干措施》[2]已提出研究制定创新药临床综合评价技术指南、推动创新药配备使用，2025年基本医保目录与商保创新药目录发布通知[3]进一步明确了药品配备、临时采购与监测责任。在既有监测安排中，应关注药品未配备或患者无法使用的原因，区分无适用患者、证据或用药条件不足、供应延迟以及支付衔接等情形：对于证据不足的，明确后续评价需回答的问题；对于供应与支付问题，按现有职责协调解决；对于无适用患者或不具备用药条件的，不宜以提高使用量为目标。"

S[116] = "在反馈机制上，医疗机构可反馈适用人群、配备状态及使用条件等方面的问题，企业反馈供应情况，相关部门在职责范围内核对支付与保障条件。制定创新药临床综合评价技术指南及开展后续评价时，可将上述信息与医保评审所用的比较药品和证据要求相结合，识别需要补充论证的事项。需要注意的是，配备与采购信息仅反映应用条件，不能替代疗效与安全性证据，涉及临床获益判断的问题可通过前述补充研究评价；纳入商保创新药目录亦不等同于基本医保报销[3]。个体资料应按授权与数据管理要求使用，保密价格信息按权限提供。由此，临床应用反馈可为企业安排后续研究提供依据，在研发、准入与使用之间形成证据持续更新的衔接机制。"

S[118] = "本文基于“制度逻辑—组织注意力”框架，综合运用政策文本编码、条文分析与访谈资料，比较药监局、医保局和卫健委在创新药评价中的关注差异，得出以下结论：第一，三部门政策文本的关注重点存在差异，药监局侧重安全性与有效性，医保局侧重经济性，卫健委安全性与经济性占比较高，但二者排序受联合发文影响；在含“创新药”一词的条款中，药监局突出创新性，医保局仍以经济性居首。第二，同一维度下三部门的评价对象、比较药品与证据要求各不相同，既有证据能否用于后续环节，需结合目标人群、比较基础及决策用途加以判断；跨环节使用评价结论时，应说明既有证据能够支持的判断及仍需补充的问题。"

S[119] = "本文的边际贡献主要体现在两方面：一是将科技创新政策研究中的创新链视角引入创新药评价研究，在统一的五维框架下同时比较药品注册、医保准入与临床使用三个环节，并以维度共现揭示关注比重之外的内容组合；二是从证据适用条件出发阐释部门评价差异对创新主体的含义，指出跨部门协同为创新提供的确定性主要体现为证据要求、比较基础与结论用途的明确。在实践层面，尽早明确比较药品与证据要求、统筹补充研究、利用临床应用反馈识别待研究问题，能够在保障评价质量的同时提高证据使用效率，增强评价规则对创新主体的可预期性，促进创新药研发、准入与使用环节的质效协同。"

S[120] = "本研究尚存在以下局限：第一，注意力占比反映政策文本对各维度的关注程度，不完全等同于评审中的实际权重，且其分布可能随后续政策调整而变化。第二，部分政策来源适用于全部药品，所测关注重点并非完全针对创新药；专门针对创新药的来源集中于药监局（10个）和医保局（5个），卫健委组文本中无此类来源。按来源拆分后，药监局和医保局的主要关注维度与全部来源一致（表7），但卫健委对创新药的评价仍需结合具体实践进一步考察。第三，五维框架以医保目录调整的评价维度为基础，《管理指南》中的适宜性（如适应证恰当性、疗程及用药是否符合指南规范）未作为独立维度统计，卫健委在该方面的关注可能未被完整反映。第四，卫健委来源较少，部分结论对个别来源较为敏感。未来研究可扩充卫健委及地方层面文本，对适宜性单独编码，并结合评审、配备与用药数据考察政策关注与实际执行之间的关系。"

S[5] = "{b:摘要：}创新药研发投入大、周期长，上市审评、医保准入与临床使用环节评价规则的衔接程度，直接影响研发主体对证据要求的预期及创新成果的转化应用。基于“制度逻辑—组织注意力”分析框架，以药监、医保、卫健三部门2017—2026年51个政策来源的4 481条句段为样本，运用大语言模型对安全性、有效性、经济性、创新性和公平性进行编码，以466条人工标注句段检验编码质量，并结合政策条文与访谈资料比较三部门的评价关注重点与证据要求。研究发现：药监局的安全性与有效性合计占68.38%，医保局的经济性占76.48%，卫健委的安全性和经济性分别占39.37%和28.35%；药监局与医保局的主要关注维度在多种稳健性检验下保持稳定，卫健委的排序则对来源构成较为敏感；同一维度下，三部门在评价对象、比较药品与证据要求上存在差异，评价结论的跨环节使用须以适用条件核对为前提。据此，从比较药品与证据要求的前置沟通、补充研究统筹和临床应用反馈3个方面提出跨部门协同路径，以增强评价规则对创新主体的可预期性，促进创新药研发、准入与使用环节的质效协同。"

S[13] = "{b:Abstract: }Innovative medicines entail long and costly development, and the alignment of evaluation rules across marketing authorization, reimbursement, and clinical use shapes innovators’ expectations of evidence requirements and the translation of innovations into practice. Based on an institutional logics–organizational attention framework, this study analyzes 4 481 passages from 51 policy sources issued by China’s drug regulatory, medical insurance, and health administration departments from 2017 to 2026. A large language model was used to code the passages on five dimensions, namely safety, efficacy, economic value, innovativeness, and equity; coding quality was validated against 466 human-labeled passages, and the findings were interpreted in light of policy provisions and interview materials. The results show that safety and efficacy jointly account for 68.38% of the attention of the National Medical Products Administration, economic value accounts for 76.48% for the National Healthcare Security Administration, and safety and economic value account for 39.37% and 28.35%, respectively, for the National Health Commission. The leading dimensions of the first two departments remain stable across robustness checks, whereas the ranking for the National Health Commission is sensitive to the composition of policy sources. Within the same dimension, the departments differ in evaluation objects, comparators, and evidence requirements; hence, the cross-stage use of evaluation conclusions should be conditioned on verifying their applicability. Accordingly, cross-departmental coordination pathways are proposed in three areas: early communication on comparators and evidence requirements, coordinated supplementary studies, and feedback from clinical use. These pathways aim to enhance the predictability of evaluation rules for innovators and to promote quality–efficiency coordination across the development, reimbursement, and clinical use of innovative medicines."
